# ruff: noqa: F401

from logging import Logger
from os import path, listdir, rmdir
from shutil import move
from typing import List, Optional, Dict, Any
import yaml

from taf.collectors.tcpdump import TcpdumpCollectorFactorySelector
from taf.collectors.l2stream3 import SbtsL2StreamCollectorFactory

from ta_tti_collector.collectors.collector_abstract_interface import TtiCollectorInterface
from ta_tti_collector.utils import get_simple_logger
from ta_tti_collector.telemetry import get_telemetry_instance


class NotKnownProfileException(Exception):
    pass


class NotKnownCollectorException(Exception):
    pass


tl = get_telemetry_instance()

class TafL2stream3Collector(TtiCollectorInterface):
    __config_dir = path.join(path.dirname(path.dirname(path.abspath(__file__))), 'config')
    __collectors_config_path = path.join(__config_dir, "taf_collectors.yaml")

    def __init__(self, dest_dir='/tmp/tti_trace_results', logger=None, **kwargs):
        # type: (str, Optional[Logger]) -> None
        """
        Setup collecting TTI trace for 5G. It uses taf.collectors: tcpdump and l2stream3
        :param dest_dir: destination directory for logs
        :param logger: Logger instance
        """
        self._register = {}
        self.logger = get_simple_logger(logger=logger, logger_name='tti_cllector', stream=True,
                                        full_path=path.join(dest_dir, 'ta_tti_cllector.log'))
        self._create_tcpdump_collector(**kwargs)
        self.trace_dir = self._check_logs_dir(dest_dir)

    def register(self, value):
        # type: (dict)  -> None
        """Add value to registry as dict."""
        with tl.trace("tti_register") as trace:
            cur_cell_ids = value[list(value.keys())[0]].get('cells', None)
            self.logger.debug('Trying to add following cells: {}'.format(cur_cell_ids))
            event_data = {"cells": "".join(cur_cell_ids if cur_cell_ids else [])}
            trace.set_attributes(event_data)

            self._register.update(value)
            self._register[list(value).pop()]['pcap'] = ""
            self._register[list(value).pop()]['is_started'] = False
            profile = list(value.values())[0].get('profile', 'default')
            self._create_l2ps_collector(profile=profile, cells=cur_cell_ids)
            self.logger.debug('Added entry: {}'.format(value))

    def start_collecting(self, alias):
        # type: (str) -> None
        """
        Setup and start taf collector l2stream3 for provided alias
        :param alias: alias
        """
        cells = self._register[alias]['cells']
        gnb = self._register[alias]['gnb']
        self.logger.info('Alias: {} start collecting for: cells {} @gNb {}'.format(alias, cells, gnb))

        try:
            self._l2ps_collector.setup()
            self._l2ps_collector.start()
            self._register[alias]['is_started'] = True
            tl.update("start_collecting", 1, {"status": "success","type": "gnb"})
        except Exception as e:
            tl.update("start_collecting", 1, {"status": "fail", "type": "gnb"})
            self.logger.error('Failed to start collecting {}: {}'.format(alias, e))
            raise

    def stop_collecting(self, alias):
        # type: (str) -> None
        """
        Stop collecting tti traces for alias.
        :param alias: alias name
        """
        if not self._is_collecting_started(alias):
            tl.update("stop_collecting", 1, {"status": "fail", "type": "gnb"})
            raise Exception("Collector for alias: '{}' has not been started".format(alias))
        self._l2ps_collector.stop()
        self._l2ps_collector.collect(self.trace_dir)
        self._l2ps_collector.teardown()

        self._register[alias]['is_started'] = False
        cells = self._register[alias]['cells']
        gnb = self._register[alias]['gnb']
        self.logger.info('Alias: {} stop collecting for: cells {} @gNb {}'.format(alias, cells, gnb))
        self._move_collected_logs(alias)
        self._remove_empty_directories()
        self._register[alias]['pcap'] = path.join(self.trace_dir, alias + ".pcap")
        tl.update("stop_collecting", 1, {"status": "success", "type": "gnb"})

    def post_test_cleanup(self):
        # type: () -> None
        raise NotImplementedError()

    def renew_cellmapping(self):
        # type: () -> None
        raise NotImplementedError()

    def _create_tcpdump_collector(self, **kwargs):
        # type: (Optional[str]) -> None
        profile = kwargs.get('profile', 'default')
        configuration = self._get_tcpdump_configuration_by_profile(profile=profile)
        self.tcpdump_cfg_name = configuration["name"]
        self._tcpdump_collector = TcpdumpCollectorFactorySelector().create(configuration, existing_arguments={})
        self.logger.debug("tcpdump collector is created")

    def _create_l2ps_collector(self, profile, cells=None):
        # type: (str, List[str]) -> None
        if cells is None:
            cells = []
        cells = [int(i) for i in cells]
        if isinstance(profile, dict):
            configuration = profile
        else:
            configuration = self._get_l2stream_configuration_by_profile(profile)
        configuration["l2_stream_configuration"] = [{"nr_phy_cell_ids": cells}]
        self.l2ps_cfg_name = configuration["name"]
        self._l2ps_collector = SbtsL2StreamCollectorFactory().create(configuration=configuration,
                                                                     existing_arguments={
                                                                         'collector': self._tcpdump_collector
                                                                     })
        self.logger.debug("L2PS collector is created")

    def _move_collected_logs(self, alias):
        # type: (str) -> None
        source = path.join(self.trace_dir, self.l2ps_cfg_name, self.tcpdump_cfg_name, self.tcpdump_cfg_name + ".pcap")
        destination = path.join(self.trace_dir, alias + ".pcap")
        move(src=source, dst=destination)

    def _remove_empty_directories(self):
        source = path.join(self.trace_dir, self.l2ps_cfg_name, self.tcpdump_cfg_name)
        if self._remove_empty(source):
            self._remove_empty(path.join(self.trace_dir, self.l2ps_cfg_name))

    def _remove_empty(self, dir_path):
        #type: (str) -> bool
        try:
            if not listdir(dir_path):
                rmdir(dir_path)
                self.logger.debug('Removed empty dir: {}'.format(dir_path))
                return True
            return False
        except OSError or FileNotFoundError:
            self.logger.warning("Cannot remove dir: '{}'".format(dir_path))
            return False

    def _is_collecting_started(self, alias):
        # type: (str) -> bool
        if not self._is_collector_registered(alias):
            raise Exception("Collector for alias: '{}' is not registered".format(alias))
        return self._register[alias]['is_started']

    def _is_collector_registered(self, alias):
        # type: (str) -> bool
        if alias in self._register:
            return True
        return False

    @staticmethod
    def _get_collectors_configuration():
        # type: (str) -> Any
        with open(TafL2stream3Collector.__collectors_config_path) as whole_config:
            return yaml.safe_load(whole_config)

    @staticmethod
    def _get_tcpdump_configurations():
        # type: () -> List[dict]
        return TafL2stream3Collector._get_collector_profiles(collector='tcpdump')

    @staticmethod
    def _get_l2ps_configurations():
        # type: () -> List[dict]
        return TafL2stream3Collector._get_collector_profiles(collector='l2ps')

    @staticmethod
    def _get_collector_profiles(collector):
        # type: (str) -> List[dict]
        config = TafL2stream3Collector._get_collectors_configuration()
        for _, collector_config in enumerate(config):
            if collector in collector_config.keys():
                return collector_config[collector]
        raise NotKnownCollectorException("collector {} does not exist".format(collector))

    @staticmethod
    def _get_tcpdump_configuration_by_profile(profile):
        # type: (str) -> Dict
        tcpdump_config_profiles = TafL2stream3Collector._get_tcpdump_configurations()
        for _, config_profile in enumerate(tcpdump_config_profiles):
            if profile in config_profile.keys():
                return config_profile[profile]
        raise NotKnownProfileException("profile {} does not exist".format(profile))

    @staticmethod
    def _get_l2stream_configuration_by_profile(profile):
        # type: (str) -> Dict
        l2ps_config_profiles = TafL2stream3Collector._get_l2ps_configurations()
        for _, config_profile in enumerate(l2ps_config_profiles):
            if profile in config_profile.keys():
                return config_profile[profile]
        raise NotKnownProfileException("profile {} does not exist".format(profile))

    @staticmethod
    def _fetch_gnb_id(value):
        # type: (dict) -> str
        return value[list(value.keys())[0]]['gnb']
